const row = $input.first().json;
let nav = {};
try { nav = $('Nav laden').first().json; } catch (e) { nav = {}; }

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:900px;margin:0 auto;}'
  + 'h1{font-size:26px;color:#fff;margin-bottom:4px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:28px;}'
  + '.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;}'
  + '.tile{background:#181b21;border:1px solid #2a2d34;border-radius:10px;padding:20px;text-decoration:none;color:#e6e6e6;display:block;transition:border-color .1s;}'
  + '.tile:hover{border-color:#5b8def;}'
  + '.tile .zahl{font-size:32px;font-weight:700;color:#fff;} .tile .zahl.zero{color:#6bcf8e;}'
  + '.tile .zahl.warn{color:#e0a854;} .tile .zahl.danger{color:#e0665a;}'
  + '.tile .label{font-size:13px;color:#9aa0a6;margin-top:4px;}'
  + '.tile.status{grid-column:1/-1;}'
  + '.hint{color:#9aa0a6;font-size:12px;margin-top:28px;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

function tile(link, anzahl, label, warnAbAnzahl) {
  const klass = anzahl === 0 ? 'zero' : (warnAbAnzahl && anzahl >= warnAbAnzahl ? 'danger' : '');
  return '<a class="tile" href="' + link + '"><div class="zahl ' + klass + '">' + anzahl + '</div><div class="label">' + esc(label) + '</div></a>';
}

const systemfehler = row.systemfehler_24h || 0;
const systemKlass = systemfehler === 0 ? 'zero' : (systemfehler >= 5 ? 'danger' : 'warn');
const systemLabel = systemfehler === 0
  ? 'Systemstatus: OK - keine Fehler in den letzten 24h'
  : 'Systemstatus: ' + systemfehler + ' Fehler in den letzten 24h (letzter: ' + fmtDate(row.letzter_systemfehler) + ')';

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const stunde = Number(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin', hour: '2-digit', hour12: false }));
const gruss = stunde >= 5 && stunde < 11 ? 'Guten Morgen' : (stunde >= 11 && stunde < 18 ? 'Guten Tag' : 'Guten Abend');

const html = pageWrap('Heute', ''
  + '<h1>' + esc(gruss) + '</h1>'
  + '<div class="meta">Stand: ' + now + '</div>'
  + '<div class="tiles">'
  + tile('/webhook/heute-handeln', row.trade_ideen_anzahl || 0, 'Trade-Ideen heute')
  + tile('/webhook/trade-review', row.offene_positionen_anzahl || 0, 'Offene Positionen')
  + tile('/webhook/trade-review', row.trade_reviews_anzahl || 0, 'Trade-Reviews zu erledigen')
  + tile('/webhook/news-pruefen', row.news_reviews_anzahl || 0, 'News zu prüfen')
  + tile('/webhook/news-pruefen', row.auffaellige_regeln_anzahl || 0, 'Auffällige Filterregeln')
  + tile('/webhook/lernvorschlaege', row.lernvorschlaege_anzahl || 0, 'Offene Lernvorschläge')
  + '<a class="tile status" href="/webhook/aktien-status"><div class="zahl ' + systemKlass + '">' + (systemfehler === 0 ? 'OK' : systemfehler) + '</div><div class="label">' + esc(systemLabel) + '</div></a>'
  + '</div>'
  + '<div class="hint">Detailübersicht mit Listen: <a href="/webhook/lernen-feedback" style="color:#8ab4f8;">Lernen &amp; Feedback</a>. Kein Kachel-Wert löst automatisch etwas aus - jede Zahl ist ein Sprungpunkt zur passenden Seite.</div>'
);

return [{ json: { html } }];
